import Foundation

// Texte der Teams & Events (Native-Port Stufe 4, 01.11.2026). ERZEUGT aus web/src/i18n/locales/*.ts —
// dort steht der Wortlaut in allen 18 Sprachen, hier nur die Kopie der Schluessel, die die App benutzt
// (team.* sowie sd.avgHrFoil/sd.avgHrGesamt). Neue Schluessel: aus der Web-Datei uebernehmen, Wortlaut nie hier aendern.
// Eigene Datei und eigener Zugriff wie LocOnboarding.swift: Loc.t() fragt sie fuer diese Schluessel zuerst.
//
// Je Sprache in Bloecke zu hoechstens 45 Eintraegen zerlegt: EIN grosses Literal ist fuer den
// Swift-Type-Checker EIN Ausdruck, dessen Kosten ueberproportional wachsen (Loc.swift hing daran schon
// einmal minutenlang). Zusammengefuehrt beim ersten Zugriff.

enum LocTeam {
    /// nil = Schluessel unbekannt (dann sucht Loc.t in den grossen Tabellen weiter).
    static func t(_ key: String, _ lang: String) -> String? {
        if let v = sprachen[lang]?[key] { return v }
        if lang == "pt-PT", let v = sprachen["pt"]?[key] { return v }
        if lang == "gsw" || lang == "de-AT", let v = sprachen["de"]?[key] { return v }
        return sprachen["en"]?[key]
    }

    static let sprachen: [String: [String: String]] = {
        var d: [String: [String: String]] = [:]
        d["de"] = zusammen([_de0, _de1, _de2, _de3, _de4, _de5])
        d["gsw"] = zusammen([_gsw0, _gsw1, _gsw2, _gsw3, _gsw4, _gsw5])
        d["de-AT"] = zusammen([_de_AT0, _de_AT1, _de_AT2, _de_AT3, _de_AT4, _de_AT5])
        d["en"] = zusammen([_en0, _en1, _en2, _en3, _en4, _en5])
        d["fr"] = zusammen([_fr0, _fr1, _fr2, _fr3, _fr4, _fr5])
        d["it"] = zusammen([_it0, _it1, _it2, _it3, _it4, _it5])
        d["es"] = zusammen([_es0, _es1, _es2, _es3, _es4, _es5])
        d["fi"] = zusammen([_fi0, _fi1, _fi2, _fi3, _fi4, _fi5])
        d["nl"] = zusammen([_nl0, _nl1, _nl2, _nl3, _nl4, _nl5])
        d["cs"] = zusammen([_cs0, _cs1, _cs2, _cs3, _cs4, _cs5])
        d["pl"] = zusammen([_pl0, _pl1, _pl2, _pl3, _pl4, _pl5])
        d["pt"] = zusammen([_pt0, _pt1, _pt2, _pt3, _pt4, _pt5])
        d["pt-PT"] = zusammen([_pt_PT0, _pt_PT1, _pt_PT2, _pt_PT3, _pt_PT4, _pt_PT5])
        d["ja"] = zusammen([_ja0, _ja1, _ja2, _ja3, _ja4, _ja5])
        d["zh"] = zusammen([_zh0, _zh1, _zh2, _zh3, _zh4, _zh5])
        d["ru"] = zusammen([_ru0, _ru1, _ru2, _ru3, _ru4, _ru5])
        d["id"] = zusammen([_id0, _id1, _id2, _id3, _id4, _id5])
        d["nb"] = zusammen([_nb0, _nb1, _nb2, _nb3, _nb4, _nb5])
        return d
    }()

    private static func zusammen(_ teile: [[String: String]]) -> [String: String] {
        var d: [String: String] = [:]
        for p in teile { d.merge(p) { a, _ in a } }
        return d
    }

